curl -sS -X POST https://slack.com/api/users.list -H "Authorization: Bearer <TOKEN>" | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'): print('ERR', d); sys.exit()
for u in d['members']:
    if 'diego' in u.get('real_name','').lower() or 'alvarez' in u.get('real_name','').lower():
        print(u['id'], '|', u.get('real_name'), '|', u.get('deleted'))
"

